        public static List<MagazineIssueContent> BuildMagazineIssues()
        {
            return new List<MagazineIssueContent>
            {
                Issue("mag.season.07", 6, 7,
                    "《边线周刊》", "夏窗开张：先救火，再做梦", "第 07 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "窗户一开，谁先慌？", "夏窗第一周：酒吧在找前锋，保级队在找命。",
                        "转会窗刚开一条缝，黑麦酒馆的求助信就先到了。主力前锋庆祝过头，周末比赛无人可用。应急招聘的规矩只有一条：先看下周能不能踢，再谈以后。", "另一头，法罗灯塔的保级警报响彻整个夏天。他们的清单不华丽：一个冷静、可靠、见过大风浪的后卫。履历上的豪门名字帮不了他们，丢球数字才可以。",
                        "夏窗第一课：需求是真的，故事不一定。", "本周清单", "宿醉前锋的替班、保级队的后卫、一位跑得比简历快的荷兰边锋。来源核对一遍，再核对一遍。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "转会观察", "应急招聘的三条纪律", "当俱乐部说“随便来一个”，恰恰是最不能随便的时候。",
                        "每年夏窗第一周，球探的邮箱里都躺着几封语气诚恳的求救信。今年最诚恳的一封来自黑麦酒馆：头号前锋在庆祝一场业余胜利之后，暂时失去了出场能力。这类需求的标准解法是找一位“即插即用”的老熟人，但本刊建议先问三个问题：他上周踢了吗？踢了多久？对手是谁？三个问题答不上来，报价单就先别签。", "法罗灯塔的求助信严肃得多。保级队的防线焦虑写在每一个丢球里，他们要的不是名气，而是一个在禁区里不发抖的人。本刊提醒：“经验丰富”在经纪人词典里约等于“年纪不小”，请把出场记录翻到最近两个赛季，再决定要不要感动。第一周的市场，耐心比钱包重要。",
                        "应急招聘签的是下周，不是下赛季。", "来信摘要", "黑麦酒馆：前锋一名，能醒着上场即可。法罗灯塔：后卫一名，要求关键时刻心率正常。",
                        "", 0, 5),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "门德斯：跑得比报价单快的人", "荷甲过人王进入自由市场，速度是真的，别的要再看。",
                        "启动第一步是教科书级别：拿球、沉肩，人已经在一米开外。反击场景里他一个人就是一套战术，长距离带球推进时，回追的后卫看起来像在进行另一种运动。经纪团队提供的集锦与公开录像口径一致，速度一项无需存疑。职业口碑不错，训练出勤稳定。", "传中质量像抽签，同一场比赛能送出妙传，也能送出边线球。身体对抗在强度升级后能否站住，需要更多样本。终结能力目前是“到场”而非“到账”。另外提醒：速度型边锋的简历折旧很快，签他之前，先想清楚你的战术里有没有他的跑道。",
                        "速度能过他，传球未必找得到他。", "样本说明", "基于三季公开录像与两场现场。经纪人集锦已按本刊规矩丢弃。与首期“41球”同理：数字先找出处，再谈感情。",
                        "player.mendes.kyle", 10, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "费雷拉：低级别联赛的防波堤", "没有豪门履历的三十六岁后卫，恰好是保级队要找的那种人？",
                        "十八个赛季，全部在低级别联赛，全部踢完。位置感是被上千次传中砸出来的直觉：不扑、不赌、不失位。指挥防线话不多，但每句都在点上。前队友说他“只是比所有人多坚持了十年”——本刊认为这句话本身就是履历。体能管理成熟，训练从不缺席。", "年龄写在身份证上，也写在回追的第一步里。面对速度型前锋，他需要整条防线帮他争取半米。没有顶级联赛经验，意味着没有顶级联赛的参照系，“保级队核心”与“低级别老兵”之间，隔着一层没验证过的窗户纸。签约前请务必现场看一场客场雨战。",
                        "他不是天才，他只是没放弃，这更贵。", "核对口径", "“经验丰富”请折算成最近两季出场分钟再阅读。保级队来信要求“关键时刻站出来”，他的样本恰好够。",
                        "player.ferreira.antonio", 16, -1)),
                Issue("mag.season.08", 7, 8,
                    "《绿金足球报》", "金元特别报道：名气的报价单", "第 08 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "海湾的支票本又打开了", "金色沙丘开出巨额报价，指名要“大家都认识的人”。问题只剩一个：名气怎么验收？",
                        "金色沙丘的来信只有一行要求加粗：知名度。能力可以谈，年龄可以谈，钱不用谈。这是转会市场上最昂贵、也最容易买错的一类需求。", "同一周，一位自称传奇球王远房亲戚的前锋回到了货架上。家谱和支票本同时出现，本刊编辑部闻到了熟悉的味道——和某人的“41球”同一个配方。",
                        "名气能卖票，但票买不来进球。", "验收清单", "名气三问：认识他的人记得他做什么？最近的高光是哪一年？高光和现在的他有什么关系？",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "市场评论", "名气汇率：一张脸能换多少分钟", "从球衣销量到出场时间，名气的兑换率每天都在变。",
                        "金色沙丘的报价逻辑并不新鲜：买名气，顺便买足球。这类交易的坑在于，名气是折旧极快的资产——它按“最近一次被提起”计价，而不是按“最近一次进球”。签约发布会上球迷欢呼的分贝，与半个赛季后替补席的温度，往往成反比。本刊建议所有想买名气的俱乐部先做一个小测试：把名字遮住，只看最近两个赛季的出场与贡献，再问自己还激动吗。", "至于“传奇的亲戚”这个品种，市场早就给出过定价：故事归故事，合同归合同。血缘无法通过体检，天赋也没有遗传证明书。当年“41球”罗里教会我们：凡是需要邻居出面作证的天赋，一律按传闻处理。金色沙丘的钱不是我们的钱，但本刊还是劝一句：支票本打开之前，先把录像打开。",
                        "遮住名字看数据，遮住数据看名字，两遍都要看。", "名词解释", "名气资产：按热搜计价，按分钟折旧。家谱优势：尚未被任何体测项目收录。",
                        "", 8, 14),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "罗萨莱斯：家谱比射术厚", "故事很动听，邻居很热情，录像很诚实。",
                        "必须公平地说：青年联赛时期的他确实有过灵气，小范围的触球和想象力带着南美街头的味道。“球王来家里吃过饭”的传闻至少说明，他从小生活在足球氛围里。营销价值也是真实存在——球衣背后印上这个姓氏，确实有人愿意买单。", "问题在于，“亲戚”两个字无法通过任何一项足球测试。成年后的比赛样本稀薄，体能储备在正式强度下能撑多久是未知数，职业态度也只有传闻级别。邻居的证词热情洋溢，但邻居的考核标准不是职业标准。若金色沙丘只为名气而来，请便；若为进球而来，请绕路。",
                        "天赋不遗传，训练量更不遗传。", "证据等级", "自述：家族遗传。佐证：邻居。可核实材料：青年联赛片段若干。本刊评级：按传闻处理。",
                        "player.rosales.diego", 14, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "莫拉：叹息之墙，真实存在", "比甲单季零封第一的门将进入市场，这次数字对得上录像。",
                        "近距离反应是顶级的：单刀球面前，他的出击时机像提前读了射门者的念头。一米内的二次扑救尤其罕见，重心丢出去了还能再捞回来。比甲单季零封场次第一，这个口径我们核对过——赛事级别、出场分钟、点球占比都站得住。本刊首期的核对清单，他全过了。", "需要提醒的是，零封是整条防线的合影，不是门将的独照。他身前那条防线纪律极佳，换一队人还能不能复制，要看新东家的防守结构。出击范围偏保守，遇到高位逼抢体系时，出球环节会受考验。价格不便宜，但贵和贵得有理，是两回事。",
                        "零封先问防线，再问门将——他两项都经得起问。", "口径核对", "零封第一：已核。样本：完整赛季。参照：格斯“第五次扑点”那年的抽查口径。结论：真实，可买，要带说明书。",
                        "player.mora.victor", 17, -1)),
                Issue("mag.season.09", 8, 9,
                    "《九十分钟》", "体能特辑：神话也要测心率", "第 09 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "时速两百公里的坦克进站了", "一个让边锋让路的翼卫，一个加时赛还在冲刺的前锋：体能神话，先过体测关。",
                        "“时速200公里的坦克”——这个称号从法国一路开进本刊编辑部。前队友的证词很统一：他训练赛一启动，大家的第一反应是让路。", "另一位“永动机”的卖点更朴素：90分钟后还能跑，加时赛还能冲。工业联本周来信说伤了七个人，老板只问一句“他容易受伤吗”。体能，突然成了硬通货。",
                        "体能是最诚实的资产，因为装不出来。", "体测提醒", "绰号不计入体测。“坦克”要看冲刺次数，“永动机”要看高强度跑占比。数字请来自追踪数据，不要来自形容词。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "专题调查", "体能神话是怎么炼成的", "从保温杯到坦克：我们对“能跑”这个词做了一次全面体检。",
                        "本刊档案柜里，体能神话分三个等级。入门级的代表是老将维克和他的保温杯——当年所有人笑他杯里泡枸杞，后来他笑到了全勤奖的领奖台上。中级神话靠数据说话：跑动距离、冲刺次数、高强度跑占比，三样齐全才算数。高级神话靠证人：“他一启动我们全让路”，听着唬人，但本刊提醒，让路也可能是礼让。体能是足球里最不容易造假的指标，因为它每场都在被当场复测。", "工业联本周的求助信把体能推成了硬通货：七名伤员躺在医务室，老板只问“他容易受伤吗”。这是本赛季最诚实的一封来信——能力可以慢慢磨，出勤率从签约第一天就开始计息。所以别笑带马拉松成绩单来应聘的人，也别急着为“坦克”掏空钱包。把追踪数据、伤病史、出场连续性摆上桌，神话立刻现出原形：有的是真的，有的只是形容词比较努力。",
                        "保温杯里的东西不重要，重要的是杯主还在场上。", "神话分级", "一级：轶事型（保温杯）。二级：数据型（马拉松名次）。三级：绰号型（坦克、永动机）。采购前请确认等级。",
                        "", 6, 21),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "科斯塔：让路是一种战术", "边路推土机挂牌，冲击力是真的，说明书也要一起买。",
                        "纵向冲击力在同位置属于稀缺品：边线附近拿球后的第一步爆发，能把整条防线压退五米。体格优势明显，对抗后不掉速、不变形，训练出勤记录干净。“时速200公里”当然是文学修辞，但“对手主动让路”的证词在三个不同来源处得到印证——恐惧本身也是战术资产。", "冲击型踢法的电费很高：上下翻飞九十分钟，续航能撑多久需要连续样本。技术细节粗糙，传中和最后一传经常跟着惯性一起出界。防守端的位置感靠身体补回来，遇到不跟他拼身体、专打身后空当的对手时会比较狼狈。买坦克，请自备刹车片。",
                        "坦克没有倒挡，这是优点，也是报价的一部分。", "样本说明", "证词三源互证，集锦另存。“时速200公里”系修辞，本刊实测栏目拒绝为形容词出具证明。",
                        "player.costa.bruno", 3, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "席尔瓦：加时赛里还在加速的人", "技术普通，续航离谱。有些球队缺的恰恰是这种球员。",
                        "跑动能力是简历里唯一加粗的部分，也确实经得起加粗：比赛末段的高速冲刺不见衰减，加时赛还能完成纵深插上。训练中的耐力口碑从青训一路带到成年队，小学体育老师“他从小参加长跑”的证词与现有表现互相印证。对以体能换机会的球队，他是即插即用的消耗品——褒义的那种。", "跑动之外的部分都偏薄：射术平平，背身与做球能力一般，机会转化经常对不起自己跑出来的距离。“永动机”型前锋的使用说明很苛刻——球队必须先能造出值得他跑的局面。若指望他解决进球问题，那是让发动机去干方向盘的活。",
                        "他能跑九十分钟，问题是你让他跑向哪儿。", "匹配提示", "工业联本周问“他容易受伤吗”，这类球员就是最好的广告。需求与供给罕见对齐，价格仍建议慢慢谈。",
                        "player.silva.marco", 6, -1)),
                Issue("mag.season.10", 9, 10,
                    "《门线月报》", "门将特辑：从手到脚", "第 10 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "现在的门将，先考脚法", "一位脚下能组织进攻的门将，和一位三年没踢正式比赛的巨星，同时出现在市场上。",
                        "门将的招聘启事变了。一支橙色球队的光头教练把话挑明：他要的不是门线上的雕像，而是后场的第一个组织者。用脚踢球，从加分项变成了入场券。", "同一份周报里，我们还读到一封伤感的简历。曾经用左脚创造无数奇迹的中场，离开赛场三年，想回来。技术录像还在，问题在身体。",
                        "门将的新考纲里，扑救只是其中一门。", "岗位变化", "旧考纲：反应、站位、摘高球。新考纲：以上全部，外加一脚四十米斜长传。备考材料请自备。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "门将专栏", "从门线到中线：一次静悄悄的革命", "当教练开始用传球次数考核门将，转会市场的排序也变了。",
                        "门将是足球里最后一个被重新定义的位置。十年前的评价标准是一张清单：反应、站位、高空球。如今清单多了一行，而且被不少教练挪到第一行：出球。光头教练们的逻辑很直接——如果门将是全队唯一永远面对进攻方向的人，那他理应参与组织。于是市场上出现了新品种：扑救合格、脚法出色的“组织型门将”。本刊提醒买家：先想清楚自己的战术需不需要这双脚，再决定为这双脚付多少钱。", "另一位本周进入视线的老将提醒我们位置的另一面：天赋从不折旧，身体会。那位曾经的世界级中场，训练录像里的左脚依然能把球传到任何坐标，但三年没有正式比赛的空白，不是集锦能填满的。门将靠脚法延长职业寿命，巨星要靠体检报告争取最后一次机会。两种回归，一个共同结论：先看最近，再看曾经。本刊对两者都保持敬意，也都保持核对。",
                        "情怀负责到场，体检报告负责上场。", "本周风向", "橙色球队：寻组织型门将。东亚方向：寻“90分钟后还能跑”的前锋。招聘启事越来越像体测通知。",
                        "", 17, 4),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "奥纳库：脚下有球，心中有图", "被改造成门将的前场球员，出球是天赋，扑救是手艺。",
                        "出球能力是真材实料：压力下第一脚触球从容，长短传都有谱，后场组织时的选位思路明显带着前场球员的视角——他本就是因反应快被改造成门将的。在之前的体系里，他长期担任后场第一出球点，这不是包装。心态沉稳，丢球后下一脚处理不慌乱，这一点比脚法更难得。", "转型的另一面也写得明白：扑救是手艺活，他的手艺只能算及格。门线反应、一对一封堵都不算强项，高球处理的稳定性一般。买他等于同时买下使用说明——球队必须能把防线推到中场，把门将的扑救需求降到最低。战术不对口，优点会闲置。",
                        "他的脚解决了你的出球，谁来解决你的扑救？", "适配检测", "先答三问再买：你的中卫能顶到中线吗？你的教练接受门将传球失误吗？你的替补门将是什么类型？",
                        "player.onaku.andre", 17, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "里瓦斯：左脚还在，日程表空了三年", "技术录像让人想鼓掌，出勤记录让人想开会。",
                        "先说好消息：最新训练录像确认，左脚的传球、远射、任意球功夫都在，视野和节奏感是本能，不会过期。职业素养口碑极佳，豪门履历与国家队大赛经历意味着他不怵任何场面。若恢复到可用状态，这笔签约的竞技上限是本期市场最高的，没有之一。", "然后是那份体检报告前的问题清单：三年几乎无正式比赛，比赛体能要从零重建；大伤之后的反复风险无法预估；恢复期的耐心与薪水同样昂贵。他最合适的角色可能不是主力，而是特定时段的胜负手。报价请按“能用的分钟数”计算，而不是按“曾经的高度”。",
                        "别为记忆付顶薪，为分钟付工资。", "核实进度", "技术：已核，属实。身体：待核，关键项。心态：自述“还想踢”，建议在合同里量化这个“想”。",
                        "player.rivas.j", 16, -1)),
                Issue("mag.season.11", 10, 11,
                    "《绿金足球报》", "从贫民区到队长袖标", "第 11 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "两种起点，一份简历", "圣保罗街头的十五岁天才，和葡萄牙低级别联赛的八队老队长，本周同时待价而沽。",
                        "卢卡斯的简历从贫民区的水泥地写起：街头足球出身，15岁被球探带走，青年队比赛里连过三人完成绝杀。南美足球的下一个名字，正在按传统流程排队出道。", "何塞的简历薄得多，也厚得多：第三、第四级别，八支球队，队长袖标戴了十几年。他本周找的是最后一份工作。山谷镇正在冲击职业联赛，他们需要见过山顶的人。",
                        "一个还没被用旧，一个已经被用透，都是资产。", "招聘对表", "山谷镇：要有顶级联赛经验的人带路。附件科技：要一个“射门时不闭眼”的门将。门槛的世界千差万别。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "人物对读", "第一份工作与最后一份工作", "我们同时读了两份简历，发现它们互为答案。",
                        "年轻天才的简历永远闪闪发光，因为没来得及留下划痕。卢卡斯的故事符合所有经典元素：贫民区、街头、15岁、球探、连过三人的绝杀。证据链也比一般的神话结实——有公开比赛画面，有青训体系的接收记录。本刊只提醒一件事：青年比赛的样本要打折看，折扣率取决于对手年龄和联赛强度。这不是泼冷水，这是汇率。贫民区走出的少年值得所有祝福，但祝福不计入报价。", "老队长的简历刚好相反：没有高光，全是日历。八支球队，十几年，第三第四级别，每个赛季都在。何塞的价值不在任何一次铲抢里，而在“丢球后有人说话”这件事本身。本周山谷镇的来信写得很诚恳：小镇需要一支职业球队，需要一个见过山顶的人带路。年轻球员负责上限，老队长负责下限。签前者赌未来，签后者买现在。预算允许的话，各来一个。",
                        "上限让球迷买票，下限让教练睡觉。", "汇率说明", "青年队高光：按对手年龄折算。低级别全勤：按联赛强度折算。领导力：暂无公式，按嗓门实测。",
                        "", 15, 16),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "卢卡斯：水泥地上练出的触球", "近年来南美最受关注的年轻人之一，这次传闻对得上画面。",
                        "小空间技术是最大资产：街头足球练出的脚下频率和变向，在密集防守里依然能用。那场“连过三人绝杀”的青年队比赛有完整画面，不是口耳相传。15岁进入职业青训，路径清晰，资料连贯——在天才营销遍地的年代，这份透明度本身就值钱。性格外向，适应门槛低。", "所有疑问都来自同一个地方：他还没在成人比赛里被验证过。青年队的身体对抗与职业联赛是两个星球，他的体格目前偏单薄。防守端的投入度未知，位置纪律还在培养期。这是一张“未来兑现型”合同，签字前请先回答：你的球队等得起几年？",
                        "天赋是真的，日历也是真的。", "样本说明", "公开画面：青年队比赛，可靠性较高。缺失项：成年联赛样本，零场。报价请按期货逻辑，不按现货。",
                        "player.vieira.lucas", 15, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "老队长费雷拉：八支球队，一副嗓门", "没踢过顶级联赛，却一直在当队长——这本身就是一种位置。",
                        "领导力是可观察的：防线站位靠他喊话维持，丢球后的第一反应是组织而不是抱怨。葡萄牙第三、第四级别辗转八队，每到一处都戴上袖标，说明更衣室投票常年有效。经验覆盖保级、升级、杯赛爆冷等各种剧本。对年轻球队，他相当于半个助理教练，还占一个出场名额。", "身体部分请直接读年龄：速度已经下降，回追覆盖面有限，连续一周双赛会很吃力。他的比赛价值随赛程密度递减，随比分焦灼度递增。别指望他拯救运动能力，他能拯救的是秩序。合同建议一年一签，出场安排建议精挑对手。",
                        "他跑不动的距离，用喊话补上。", "使用建议", "适用：领先后的最后二十分钟、更衣室、客场雨战。不适用：对攻、冲刺反击、任何需要回追三十米的时刻。",
                        "player.ferreira.jose", 16, -1)),
                Issue("mag.season.12", 11, 12,
                    "《边线周刊》", "状态起伏定价指南", "第 12 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "幽灵与闪电，价格怎么标", "一个没速度但总出现在落点上的射手，一个能赢比赛也能消失的边锋。",
                        "卡洛斯·奥尔特加在西班牙第四级别踢了七年，拿过金靴，速度约等于无。但禁区里的嗅觉，让后卫怀疑自己看球的方式。", "路易斯·埃雷拉辗转九队，快得像发型上那道闪电，状态曲线像过山车。前队友的评价一字不改：“他能一个人赢下比赛，也能整场摸不到球。”",
                        "状态起伏不是缺陷，是需要重新定价的资产。", "定价难题", "幽灵型：按进球数报价，还是按出场数？闪电型：按最好那场报价，还是按平均那场？本期正文有解。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "估值方法", "波动不是风险，糊涂才是", "给“不稳定”标价之前，先搞清楚它不稳定的原因。",
                        "转会市场对“状态起伏”向来态度粗暴：直接打折。但本刊的十九张表——对，就是米洛那十九张表——早就说明一件事：波动也分品种。第一种是环境型波动，换个体系就稳定，比如那些“在A队隐身、在B队封神”的人。第二种是随机型波动，连他自己都预测不了，比如闪电型边锋。第三种是伪波动：出场被切得粉碎，分钟数碎成渣，谁来了都得“状态不稳”。三种波动，三种价格，混在一起谈就是送钱。", "禁区幽灵是另一道定价难题：他的产出高度集中——不抢断、不组织、不回防，只做一件事，出现在球即将出现的地方。这类球员的正确估值方式是按“每90分钟预期贡献”，而不是按“全场存在感”。存在感低得可怕，产出高得稳定。本周雾港要“丢球后有人说话”的后卫，群岛要“一个人顶三个人”的万能工——需求写得越具体，估值越不容易被故事带跑。",
                        "把波动拆开看，有的是风险，有的是折扣。", "三种波动", "环境型：换队可解，放心买。随机型：无法预测，按均价买。伪波动：样本被切碎，其实是赚了。",
                        "", 23, 1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "奥尔特加：你在找他，他在落点上", "第四级别七年两夺金靴，速度没有，嗅觉满格。",
                        "禁区内的预判是他的全部，也是他的护城河：传中还在空中，他已经开始向落点移动。两脚都能终结，小动作摆脱很实用。金靴是公开记录、可核的硬产出。七年同一级别，稳定本身就是信息：教练年年换人，他的首发年年不换。价格预计不贵，性价比曲线漂亮。", "幽灵的另一面必须说清：没有速度意味着没有纵深，防线前提时他的威胁减半。不参与逼抢，防守约等于十打十一。对更高强度联赛的适应性完全没有样本。他是体系的奢侈品——球队必须先能把球稳定送进禁区，他才存在。买他之前，先数清楚自己队里有几个能传中的。",
                        "他不追球，他去未来等球。", "核查清单", "金靴：已核。所在级别：第四级。更高级别样本：无。结论：产出真实，成色请按联赛级别折算。",
                        "player.ortega.carlos", 4, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "埃雷拉：闪电为什么换了九朵云", "速度顶级，状态玄学，九支球队各有各的版本。",
                        "纯速度是他的硬通货：启动那一下在任何级别都够用，反击场景里他一个人就是纵深。状态在线时的他是集锦制造机，“一个人赢下比赛”的场次确实存在，且有画面。九支球队的经历换个角度看也是信息——每支球队都愿意赌他一次，说明天赋的可见度极高。", "但九支球队也都没有留住他，这是简历上最大的一句潜台词。状态起伏的原因从未被说清：是伤病管理、战术适配还是职业习惯？三种答案对应三种风险等级。体能储备一般，情绪随比赛走势波动明显。他只适合作为“变招”而非“基石”签约，合同里请写满与出场挂钩的条款。",
                        "签闪电的正确姿势：按灯泡的寿命谈价。", "背景调查", "九队履历：已核。离队原因：九个版本，互不重合。建议面谈时直接问他：第十支球队想听什么。",
                        "player.herrera.luis", 0, -1)),
                Issue("mag.season.13", 12, 13,
                    "《冠军之路》", "耐力特辑：另一种天赋", "第 13 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "马拉松第56名，来踢中场", "一个被青训放弃后跑马拉松的中场，一个从工地回到球场的后卫。",
                        "利亚姆·库珀17岁被职业青训放弃，之后的履历里有一行特别醒目：伦敦马拉松第56名。现在，他想用这双腿重新敲开职业足球的门。", "杰克·特纳的故事在另一个工地：多年建筑工人，重返全职足球。队友说他踢球像搬砖——简单、直接、有效。本周两支球队的来信都在找“耐用的人”，巧了。",
                        "被放弃过的人，最懂得不下场。", "来信对照", "铸铁队：要一个“不介意踢得难看”的后卫。两半联：要一个“90分钟都能被看见”的前锋。两位主角请对号入座。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "深度报道", "第二人生的体能账", "离开过足球又回来的人，身体账本和别人不一样。",
                        "被青训放弃，是足球世界里最普通的事故；从马拉松赛道跑回来，才是新闻。库珀们的优势写在肺里：覆盖面积大，反复冲刺不发怵，九十分钟的供能系统是长距离项目亲手打造的。短板也写在同一份履历里：17岁以后缺了数年系统训练，技术细节停在少年时代。这类球员的评估要拆开两张表：体能表按成年人标准，技术表按回炉青训标准。两表都过，才叫捡到。", "建筑工人特纳提供的是另一种体能逻辑：不是跑出来的，是扛出来的。多年体力劳动给他的核心力量、对抗习惯和对疼痛的钝感，是健身房练不出的品种。队友那句“踢球像搬砖”其实是褒义——防守没有多余花哨，铲球和头球像一道道工序，简单、直接、有效。本刊提醒：“第二人生”球员的伤病史要往入职前翻，工地损耗也是损耗。体检，请翻到第一页。",
                        "一张是跑出来的肺，一张是扛出来的背。", "体检提示", "第二人生球员的体检要加两页：足球前的职业史、足球外的运动史。损耗和天赋可能来自同一个地方。",
                        "", 6, 16),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "库珀：肺是满的，技术是赊的", "马拉松第56名货真价实，问题是足球不是42公里直道。",
                        "跑动能力有公开纪录背书：伦敦马拉松第56名，不是“据说很能跑”。放到球场上，表现为覆盖面积大、往返不知疲倦、比赛末段强度不降。17岁前的青训底子还在，无球跑动的意识比同龄人成熟。职业态度不用怀疑——被放弃后自己跑回来的人，自律是默认配置。", "技术环节全面偏科：传控精度一般，高压下的第一脚触球容易露怯，进攻三区几乎没有产出。被放弃后的数年空窗意味着战术理解停在半职业水平，需要从头补课。他的定位只能是体系里的“跑件”，指望他组织或终结都是误诊。合同友好，耐心要自带。",
                        "马拉松不考传控，但职业足球考。", "样本说明", "马拉松名次：公开可查，已核。半职业联赛画面：若干，强度有限。结论：肺是真的，其余按半成品计价。",
                        "player.cooper.liam", 6, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "特纳：防守像搬砖，是表扬", "从工地直接走回球场的人，铲球和头球都带着工龄。",
                        "对抗是他的母语：身体强壮，铲球时机老到，头球落点判断准，定位球攻防两端都能用。比赛风格干净直接，没有多余动作。性格踏实，训练出勤率极高，教练布置的任务按工序完成——今天砌墙，明天还砌墙，质量稳定。", "转身速度和脚下频率是天然短板，面对灵巧型前锋会被反复调头折磨。出球基本只有安全选项，体系要求他参与组织时会露馅。多年工地生涯留下的劳损，需要队医逐页核对。他的上限肉眼可见，下限也肉眼可见——买他买的是后者，请按需下单。",
                        "他不惊艳任何人，也不背叛任何人。", "适配提示", "适合：铸铁队本周“干脏活”岗位。不适合：要求后卫第一脚出球穿透两条线的体系。说明书随人附赠。",
                        "player.turner.jack", 3, -1)),
                Issue("mag.season.14", 13, 14,
                    "《九十分钟》", "安全球与高空球", "第 14 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "安全传球是门手艺", "一个白天上班晚上练球、从不冒险的中场，和一个因身高被梯队放弃的门将。",
                        "佛朗哥·比安奇的踢球哲学一句话能说完：永远不传给可能丢的那个人。教练的评价耐人寻味：“他不会创造机会，但很少让别人创造机会。”", "米格尔·纳瓦罗的噩梦写在体检表上：身高不够，梯队再见。但他的出击成功率排在西班牙第三级别第一——老鹰抓高空球，靠的是起跳时机。",
                        "被低估的人的共同点：缺点一眼见底，优点要算。", "本周来信", "数据之光俱乐部：“只要以前进过很多球，把履历发来就行。”本期没有这样的前锋，只有两种更安静的答案。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "战术评论", "无聊的价值，与被拒绝的理由", "有些球员的优点不会上集锦，只会出现在教练的睡眠里。",
                        "“安全传球”在球迷词典里是骂人的话，在教练词典里是控球率的另一种写法。比安奇式中场的真正价值，要从反向数据里读：他在场时，球队因失误被反击的次数有多少？答案往往漂亮得无聊。这类球员的评估陷阱在于，集锦时代没有人为“没发生的失误”做视频。本刊建议用老办法：看全场，看队友失误时他在哪个位置补。答案会替你报价。", "纳瓦罗的“身高问题”则是另一种市场失灵。门将的身高要求有其道理：覆盖面积、高空球、出击范围。但“身高不足所以放弃”是一条懒惰的推理链，正确的问法是：他的起跳时机、落点预判和出击决策，能否对冲那几厘米。第三级别出击成功率第一，至少说明对冲部分成立。被拒绝过的人里常有宝贝，前提是你把“拒绝的理由”重新审一遍，而不是直接继承。",
                        "市场最大的偏见，是把别人的结论当自己的考察。", "重审清单", "前任放弃他的理由是什么？该理由在你的体系里还成立吗？有没有数据反证？三问之后，再谈价格。",
                        "", 3, 11),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "比安奇：不丢球，是他的全部战术", "白天在小企业上班，晚上训练，传球选择保守到极致。",
                        "比赛纪律性极强：位置感好，出球永远选最安全的那条线，失误率低到教练愿意为他改战术板。作为半职业球员，训练出勤和比赛态度无可挑剔，性格温和，是更衣室的稳定因素。对预算有限、先要“别再稀里糊涂丢球”的球队，他是即插即用的止血带。", "进攻贡献接近零：不冒险意味着不创造，向前传球的比例低得会让进攻教练失眠。半职业到职业的强度跨越是最大问号，他从未被真正的高压逼抢检验过。白天上班的合同结构也意味着体能储备有限。他是下限型签约——别幻想上限，上限不在他身上，在你的前锋身上。",
                        "他不创造机会，也不创造灾难。", "信息核实", "教练评语“很少让别人创造机会”未经独立核实，但与比赛画面对得上。证据等级：可信，待强度复测。",
                        "player.bianchi.franco", 3, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "纳瓦罗：被身高拒绝，被落点收留", "梯队嫌他矮，第三级别的出击榜不嫌。",
                        "反应速度和起跳时机是他的补偿机制：对传中落点的预判极准，出击果断，高空球处理方式成熟——先判断拿不拿得到，再决定出不出去。西班牙第三级别出击成功率第一，公开数据可查。被放弃的经历没有留下怨气，只留下准备活动比别人做得更早的习惯。价格合理，态度免检。", "身高带来的限制真实存在：面对高点轰炸型中锋，他需要防线前置保护；远角吊射的覆盖半径吃亏。第三级别到更高级别的传中质量不可同日而语，成功率要打联赛系数。另外样本集中在一支球队、一种打法，体系迁移的适应性待验证。签约前请安排一场“高空球压力测试”。",
                        "身高是体检表给的，出击榜是他自己挣的。", "折扣系数", "第三级别数据按惯例打折，但“出击成功率第一”打折后仍是第一。建议实测：连续三天，只练传中。",
                        "player.navarro.miguel", 17, -1)),
                Issue("mag.season.15", 14, 15,
                    "《午后体育》", "四百万粉丝与一双球鞋", "第 15 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "四百万粉丝，能换九十分钟吗", "一位全网知名的网红想圆职业梦，一位业余联赛的好好先生想试试水。",
                        "罗伯特·海耶斯的简历附件是账号后台截图：四百万粉丝。他的视频里球技华丽，评论区一致认为他该踢职业。他本人也这么觉得。", "另一位安德烈·莫雷拉就朴素多了：本地业余队边锋，助攻多，人缘好，自己找上门来问“有没有机会”。而灯塔工厂还在找一个“长传来了先别摔”的中锋——流量和热情，都帮不上这个忙。",
                        "流量能兑换发布会，兑换不了出场时间。", "鉴别要点", "视频可以剪辑，比赛不能。粉丝数是运营数据，不是运动数据。两者都对，但别用前者给后者报价。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "现象观察", "流量货币化，出场稀缺化", "从“41球”到“四百万粉”：数字越大，越要问出处。",
                        "本刊创刊那年学会的第一课，来自罗里的“41球”：数字本身不会说谎，但数字的口径会。四百万粉丝同理——它是真实的社会资产，能带来球衣销量、赞助谈判和发布会直播的人气，这一点不必酸。问题在于，足球俱乐部同时是每周末接受公开审计的机构：首发十一人里没有“剪辑”这个职位。流量型签约的正确姿势，是把商业合同和竞技合同分开签，分开考核，分开宣布。", "业余神话则是流量的反面：没有数据，只有人缘。“队友都很喜欢他”“助攻很多”——这类评价的可靠性约等于邻居证词，本刊评级：按传闻处理。但注意，传闻不等于错误，只等于未验证。正确的做法是给一次低成本的验证机会：公开试训、跟队两周、踢一场有记录的对抗赛。神话不怕检验，怕的是永远不检验。顺便一提，本刊至今记得卡洛用三明治挡住号码的那个下午——那是对“名气”最诚实的一次处理。",
                        "当年的41球教会我们：大数字都要配上出处。", "本刊评级", "粉丝四百万：真实，与足球无关。助攻很多：待核。队友喜欢：与转会无关，与食堂有关。",
                        "", 8, 22),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "海耶斯：镜头里的球王", "视频里的技术是真的，比赛里的证据是零。",
                        "公平地说，他的球感不是演的：视频里的颠球、小范围控球有真功夫，明显是从小踢过球的人。镜头感、表达欲、亲和力都是职业级别——如果“职业”指的是发布会的职业。对需要曝光度的俱乐部，他的商业价值清晰可算：粉丝画像、互动数据、带货记录，全部公开可查。", "竞技部分则完全空白：没有成年正式比赛记录，没有体测数据，没有对抗样本。视频是剪辑的艺术，单挑野球和十一人制是两个项目。年龄也不站在“从头培养”这一边。若签他，请把商业条款与竞技条款分开：发布会可以压轴，首发需要考核。顺序千万别反，反了就是事故。",
                        "他能卖出门票，问题是谁来赢下比赛。", "证据等级", "账号数据：平台可查，已核。比赛样本：无。证据等级：未验证。建议流程：先公开试训，再开发布会。",
                        "player.hayes.robert", 8, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "莫雷拉：业余联赛的好好先生", "助攻多、人缘好、防守粗糙——业余市场的标准画像。",
                        "优点是肉眼可见的那种：边路传中质量在业余层面出挑，定位球脚法有内容，前场配合意识好，“助攻很多”的口碑与有限的画面材料能对上。性格是更衣室资产，自己找上门来谈，动机纯粹，要价朴素。对预算紧张、需要进攻套路补充的球队，试错成本极低。", "短板同样肉眼可见：防守端的选位和对抗都粗糙，身后的走廊常年开放。业余到职业的距离，比他的传中弧线大得多——体能、节奏、身体，每一项都要重新考试。“队友都喜欢他”是温暖的评价，但职业足球的考题写在别处。建议流程：先试训，先短约，先做具体的梦。",
                        "人缘帮你进更衣室，防守让你留在名单里。", "成本测算", "签约成本：低。验证成本：两场公开试训。潜在收益：一位会传中的轮换。潜在风险：一条开放的边路走廊。",
                        "player.moreira.andre.amateur", 5, -1)),
                Issue("mag.season.16", 15, 16,
                    "《绿金足球报》", "五人制魔法，十一人制考卷", "第 16 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "小场魔法师，敢来大场吗", "五人制赛场最灵巧的脚，和西3最稳定的低成本射手，本周都在货架上。",
                        "迪奥戈·佩雷拉在五人制赛场是另一种生物：重心低、变向快，球像粘在脚上。球探报告里写着本期最美的一句话：“他最危险的时候，是没人知道他准备干什么的时候。”", "卡洛斯·富恩特斯走的是另一条路：地区联赛一级一级踢上来，过去五个赛季进球全部上双。没有魔法，只有到账记录。预算型买家请注意：这个名字值得抄下来。",
                        "魔法负责过人，账簿负责进球，都要核验。", "换算说明", "五人制技术：按场地与节奏折算。低级别进球：按联赛强度折算。折算后仍然成立，才叫真本事。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "专题分析", "小场到大场，隔着多少米", "五人制出品的球员越来越多，转会市场需要一张换算表。",
                        "五人制是技术的高压锅：场地小、节奏快、触球次数多，从那里出来的球员，脚下频率和小空间处理是系统自带的。但换算从来不是免费的：十一人制意味着更长的冲刺距离、更少的触球机会、更高的体能门槛。“技术细腻”在小场是天赋，在大场只是入场券。评估五人制球员，本刊的清单有三行：无球时干什么？被身体碾压时怎么办？七十分钟后还剩什么？三个问题都答得上，魔法才值钱。", "低成本射手是另一种换算题：连续五个赛季进球上双，这种稳定性比任何单季爆发都稀有。问题同样来自级别——西3的后卫与更高级别的后卫，防守的提前量完全不同。“稳定”能不能跨级别迁移，历史答案是：一部分能，看类型。靠速度的难迁移，靠预判和射术的迁移率高得多。富恩特斯属于后一类，这是他的好消息。坏消息是：检验迁移率的唯一方法，还是买回去踢。",
                        "级别之间的汇率，只有上场才结算。", "本周联动", "未来之星俱乐部在找二十岁上下、值得长期培养的中场。本期两位都不在该货架，但换算表通用。",
                        "", 4, 10),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "佩雷拉：球在他脚下会隐身", "五人制赛场的魔术师，十一人制的准考证还没领。",
                        "小空间技术接近天花板：低重心、脚下频率、变向的欺骗性，在五人制的高压锅里炼到纯熟。一对一几乎不可防，球探那句“没人知道他准备干什么”不是修辞，是对位者的普遍体验。比赛气质松弛，越是密集防守越来劲。这类天赋在僵局时刻是稀缺资源。", "十一人制的三道考题他全没交卷：长距离往返的体能储备未知，无球阶段的跑位习惯待建，被身体碾压后的应对没有样本。五人制的续航逻辑与大场不同，他能保持强度多久，需要实测。建议的签约结构：先梯队或杯赛试用，把“魔法”翻译成“分钟”，再谈长约。",
                        "魔法是真的，施法范围待测。", "实测方案", "第一周：体能基线。第二周：对抗赛。第三周：连续两场。三项达标再进大名单，顺序别乱。",
                        "player.pereira.diogo", 10, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "富恩特斯：五个赛季，全部上双", "没有华丽技术的射手，有最华丽的东西：到账记录。",
                        "稳定性是他简历的骨架：西3过去五季，进球全部上双，不靠点球堆砌，不靠单季爆发。射术扎实，双脚和头球都有终结手段，禁区内第一脚触球是为射门服务的。无球时愿意做脏活，压迫执行不含糊。“猎人”的绰号来自跑位习惯：不显山露水，专等后卫眨眼。", "上限问题必须直说：他从未在更高级别证明过自己，单兵爆破能力一般，需要体系持续供弹。年龄已过“培养”窗口，买他是买现在，不是买未来。五季稳定也意味着没有惊喜藏在简历里——所见即所得。对预算型需求，这叫对口；对梦想型买家，这叫劝退。",
                        "他不许诺惊喜，他只重复到账。", "口径核对", "五季上双：逐季核对，属实。点球占比：正常区间。对手强度：西3标准。结论：数字干净，折算后可下单。",
                        "player.fuentes.carlos", 23, -1)),
                Issue("mag.season.17", 16, 17,
                    "《边线周刊》", "年龄成谜与跑动成山", "第 17 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "他到底多大？这是个问题", "一位资料栏只写“年龄符合注册要求”的前锋，和一位场均跑18公里的压迫狂。",
                        "阿里·哈桑的履历表干净得可疑：青年联赛半场三球出道，随后资料页只剩一句“年龄符合注册要求”。队友说，他从不谈过去，只说“我踢球的时间比你们知道的更久”。", "托马斯·里德的简历则精确到小数点：19岁离开职业足球，23岁回来，如今场均跑动18公里，前场压迫从第一分钟进行到补时。本周热搜队还在找“能上新闻的人”——“幽灵”已经上了。",
                        "一份简历没有年龄，一份简历全是里程。", "核实难度", "年龄之谜：注册文件合规，但合规不等于透明。跑动18公里：追踪数据可查。一个要猜，一个要量。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "调查报道", "年龄之谜的三种解法", "当一名球员的年龄成为谜题，猜猜看谁在付学费。",
                        "足球史上的年龄谜题大致分三类。第一类是登记事故：出生地在哪，档案就在哪，纸面年龄与骨骼年龄各说各话。第二类是营销策略：年轻五岁，报价翻一番，“幽灵”型前锋的经纪人最懂这个汇率。第三类是自我保护：老将把年龄藏进迷雾，因为市场对三十五岁之后的每一岁都格外残忍。三种谜题对应三种核查：查档案、查早年比赛记录、查体测与骨密度报告。本刊提醒：“从不谈过去”本身不是罪证，但绝对是尽调清单的第一行。", "与幽灵相对的，是把一切写在脸上的压迫狂。里德们的逻辑是透明的：场均18公里，压迫次数、回追距离，全部可查可量。这类球员的风险不在信息，在结构——高强度压迫是消耗品，19岁离开又23岁回来的人，身体的折旧曲线要单独画。本周热搜队想要“上新闻的人”，本刊反而建议他们看看压迫狂：18公里这个数字，比任何热搜都更接近足球本身。",
                        "谜题留给档案室，跑动留给计步器。", "尽调清单", "注册文件：合规，已查。早年记录：缺失。身体报告：需授权。结论：可签，但请为“谜”留一个条款。",
                        "", 21, 22),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "哈桑：幽灵的年龄，猎手的脚", "冷静、狡猾、老练，身体状态却像刚进职业足球的年轻人。",
                        "比赛内容老练得可怕：跑位时机、假动作的耐心、终结前的冷静，全是“踢过很多年”的痕迹。青年联赛半场三球的出道战有据可查，门前的本能没有过期。最难得的是身体状态——速度、变向、连续作战能力保持得像二十出头。“年龄符合注册要求”之外，他的体能本身就是一份反证。", "谜的部分必须写进报告：年龄成谜意味着职业生涯长度无法预估，报价年限缺乏锚点。不谈过去意味着背景核查存在盲区。巅峰期为何长期游离于主流视野之外，没有任何权威解释。证据等级：中等，关键项缺失。签约建议：年限从短，条款从严，把“谜”的定价权握在自己手里。",
                        "他踢了多久不重要，还能踢多久才重要——而这恰恰不知道。", "证据等级", "自述：“比你们知道的更久”。佐证：队友转述。档案：合规但空白。评级：中等，合同年限请自行加保险。",
                        "player.hassan.ali", 4, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "里德：18公里，从第一分钟开始", "放弃过足球又跑回来的人，如今用跑动量重新定义前锋。",
                        "前场压迫是他的产品说明书：场均18公里不是修辞，是追踪数据。压迫路线聪明，不是瞎跑——封传球线路、逼后卫用弱脚、把出球赶向边线，一套流程完整执行。19岁离开、23岁归来的经历，反而给了他同龄前锋没有的成熟：位置纪律好，情绪稳定，战术板执行到厘米。", "消耗的账本同样要读：18公里的背后是恢复成本，连续一周双赛时强度能否维持需要样本。进攻三区自己的终结能力中等，压迫制造的球权转化，依赖队友跟进质量。伤病史要翻到19岁那一页，看当初为何离开。他是体系放大器——体系越强他越值钱，反之亦然。",
                        "他跑的不是距离，是对手的处理时间。", "样本说明", "18公里：追踪数据，已核。覆盖赛季：最近两季。待查项：密集赛程下的强度曲线。复测窗口：冬歇前。",
                        "player.reed.thomas", 6, -1)),
                Issue("mag.season.18", 17, 18,
                    "《九十分钟》", "九年全勤与十个位置", "第 18 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "九年全勤，表都没他准", "一位连续九季出场超30次的中场，和一位从前锋踢到后卫的万能补丁。",
                        "路易斯·法里亚的体检报告，医生看了想收藏。连续九个赛季出场超过30次，没有伤病，没有停赛风波，像钟表一样打卡上下班。", "马库斯·富恩特斯的简历只有一个位置描述：“都可以”。前队友的证词言简意赅：“哪里缺人他都能补”。对了，他与本赛季早些时候那位“猎人”富恩特斯没有亲属关系，本刊已核实。",
                        "可靠是足球里最被低估的天赋。", "可靠性口径", "全勤：看出场记录与缺席原因。全能：看每个位置的分钟数，而不是听“都能踢”。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "专栏", "可靠性，一种沉默的产能", "市场为天赋付溢价，为可靠性付工资——应该反过来想想。",
                        "每年转会窗，头条属于天才，工资单属于可靠者。法里亚式中场不生产集锦，只生产“教练不用想这个位置”的安心感——九个赛季里，他的历任主帅换了一茬又一茬，每个人的首发布置会都从他名字写起。可靠性的经济学很简单：一个位置九年不需要买替补、不需要应急预案、不需要战术B计划，省下的转会费和焦虑折现后是个惊人的数字。本刊建议把“缺席成本”写进每份评估报告。", "万金油球员则是可靠性的另一种形状：他不是每天都可靠，而是到处都可用。“哪里缺人补哪里”听起来像夸奖，评估时却是道难题——每个位置都踢过，意味着每个位置都要单独定价。群岛队此前那句“一个人顶三个人”说得很形象，但请记住：三个位置的出场时间，不能叠加成三个人。万金油的正确用法是填空，不是重建。圣杯学院本周在找“私生活检点、值得培养”的年轻人——两位本期主角超龄了，但职业品质这门课，他们早已毕业。",
                        "钟表不惊艳，但它从不迟到。", "核算公式", "缺席成本＝替补溢价＋应急预案＋更衣室焦虑。全能折现＝位置数×单位置均价÷体能上限。请自行代入。",
                        "", 23, 6),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "法里亚：连续九年，场场在册", "不出集锦的中场，出全勤记录。体检报告干净得像出厂设置。",
                        "可靠性是硬数据：连续九个赛季出场30+，无重大伤病，无纪律停赛，出勤曲线平得像一条直线。踢法服务于稳定：传控安全，位置纪律严明，跑动量常年在线。教练更替不改其位，说明战术兼容性极强。对任何需要“忘掉这个位置”的球队，他就是答案本身。价格也透着靠谱——没有溢价项。", "硬币的另一面：九年的稳定也意味着九年的上限清晰可见。他不提供爆点，节奏偏慢，高强度逼抢下的出球会趋于保守。年龄已站在合同短年化的一边。“从未受伤”是运气与体质的合谋，不是永动保证书，保险条款照买。买他买的是确定性，请别在签约后抱怨确定性的无聊。",
                        "买他不为惊喜，为不用想。", "核查记录", "九季出场：逐季核对，属实。体检：异常健康，原文如此。缺席历史：近乎空白。结论：可签，年限从短。",
                        "player.faria.luis", 23, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "富恩特斯：十个位置，一份工资", "“哪里缺人他都能补”——这句话要按位置逐个验收。",
                        "多功能性是真实的：地区联赛多年，前场到后场的出场记录都能翻到，每个位置都能完成基本任务，战术理解因此高于同水平球员。性格随和，临危受命不怯场，杯赛轮换和伤病潮里他是教练的备胎箱。工资预期温和，对薄预算球队，他一个人就是名单深度的充值卡。", "验收时必须拆开看：“都能踢”不等于“都踢好”，他在每个位置的上限都是“够用”，没有一个是“出色”。体能一般，补边后卫这种高消耗位置时续航吃紧。地区联赛的对抗强度与职业赛场的差距，会同时考验他所有的位置。正确用法：特定场次的填空者。错误用法：建队基石。",
                        "他能填任何坑，前提是你别把坑挖太大。", "验收方法", "逐位置核对分钟数与对手级别，“都能踢”按最弱一环定价。友情提示：门将位置不在其列，别被热情冲昏头。",
                        "player.fuentes.marcus", 1, -1)),
                Issue("mag.season.19", 18, 19,
                    "《门线月报》", "板凳深处与牌堆之上", "第 19 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "替补席上的冠军奖牌", "一位拿着冠军奖牌却常年坐板凳的门将，和一位黄牌比进球多的边后卫。",
                        "欧文·哈里斯的履历有个反直觉的注脚：杯赛冠军成员，长期替补。他的价值写在别人的表现里——主力门将状态神勇的那些年，训练场的标准是他定的。", "鲁伊·卡多索的统计页则是另一种奇观：连续两个赛季联赛黄牌王。防守侵略性拉满，禁赛记录同样拉满。预算联本周在找“低成本高产射手”——这两位都不是射手，但“高产”这个词，黄牌榜上那位很熟。",
                        "板凳深度不够时，冠军经验会硌得人疼。", "本周岗位", "预算联本周来信：要低成本高产射手。本期一位守门、一位领牌，均不符合——这正是转会窗的幽默感。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "门将专栏", "第二门将的经济学", "替补门将是足球里最贵的奢侈品，直到他突然变成必需品。",
                        "一支球队每年在第二门将身上花的钱，看起来像给空座位买票。直到主力门将受伤那一周，整个赛季突然押在那个坐了一年板凳的人身上——这时候再贵的工资都显得便宜。好的第二门将是稀有品种：水平要接近主力，心态要接受替补，训练要维持标准，出场要即插即用。四条同时满足的人，市场上屈指可数。哈里斯的冠军奖牌和多年替补履历恰好说明：他早就学会了这门反人性的手艺。", "黄牌收藏家则是另一种成本核算。侵略性是他的产品，禁赛是产品的运费——连续两个赛季黄牌王，意味着每个赛季都有几场比赛，你的边路要自己想办法。算账的正确方式不是问“他会不会停赛”，而是问“停赛那几场丢多少分，在场那几场抢多少分”。如果后者更大，黄牌就是税而不是病。当然，税率高到影响现金流时，财政再健康的俱乐部也该考虑转型。",
                        "替补的价值平时看不见，看台看得最清。", "成本公式", "第二门将价值＝主力缺阵概率×赛季权重。黄牌成本＝停赛场次×对手强度−侵略性收益。滚动核算。",
                        "", 17, 9),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "哈里斯：板凳上的指挥官", "冠军奖牌是真的，替补也是真的，这两件事并不矛盾。",
                        "指挥防线的能力是门将里的第一梯队：嗓门、手势、站位调度，整条后防线在他的口令里移动。冠军赛季虽未打满，更衣室与训练场的贡献有口皆碑。扑救基本功扎实，准备活动职业到刻板。作为“随时能进首发”的第二门将，他的履历几乎是为这个岗位量身写的——哪家球队贴出这类需求，照着他抄就行。", "疑问集中在“节奏”二字：长期替补意味着比赛感觉需要预热，突然进首发的前两场，通常是他最脆弱的时候。年龄增长后，反应的下坡不可避免，只是被经验掩盖得很好。习惯了强队防线的他，若去一支被压着打的球队，指挥体系要重建。合同友好，但请把“出场激励”写细一点。",
                        "他指挥了整条防线，除了自己的出场时间。", "适配说明", "适合：有主力门将、要竞争与保险的球队。不适合：需要他立刻场场首发的球队。预热两场，然后放心。",
                        "player.harris.owen", 16, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "卡多索：侵略性的税率", "连续两季黄牌王，防守是真的凶，停赛也是真的多。",
                        "边路防守的存在感拉满：贴身、下脚快、对抗欲望强，对方边锋拿球前要先做一次心理建设。他的侵略性不全是鲁莽——多数犯规发生在战术需要的位置，属于“聪明的脏”。缠斗能力强，比赛气质硬，落后时刻是少数还敢做动作的人。多次被足协禁赛的记录本身，也证明他的动作常年在规则边界办公。", "成本页同样清晰：黄牌王的赛季意味着固定的停赛缺席，关键场次的停赛风险是战略级问题。纪律记录还可能带来裁判的“重点关注”——同样的动作，别人黄牌他可能升级。位置感的短板靠侵略性掩盖，遇到耐心的对手会被钓鱼。签约前请先看看你的替补边后卫是谁：他每年都要上场的。",
                        "他的犯规都懂战术，停赛也懂——专挑关键场次。", "风险评估", "黄牌纪录：连续两季，已核。禁赛场次：可量化。裁判印象分：不可量化但真实存在。预算请预留替补方案。",
                        "player.cardoso.rui", 11, -1)),
                Issue("mag.season.21", 19, 21,
                    "《冠军之路》", "重拳与重注", "第 20 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "拳击手改行踢中卫", "一位拿过青少年重量级拳王的后卫，和一位过人成功率一成的天才赌徒。",
                        "瑞安·凯利青少年时期双线作战：白天练足球，晚上练拳击，顺手拿了个青少年重量级冠军。如今他把背身作战的习惯带进禁区——对方中锋先撞到的，永远是他的前臂。", "里卡多·门德斯的数据会让分析师沉默：十次过人，九次失败。但那一次成功，可能直接赢下比赛。对了，他与第七期那位荷兰飞翼纯属同姓，命运的相似到此为止。",
                        "一个从不退，一个从不稳，都是票房。", "本期看点", "拳台纪律能否换算成禁区纪律？一成成功率为什么还有人排队？本刊再次提醒：先算期望值，再谈魅力。",
                        "", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "专题", "对抗与期望：两种另类资产", "拳台来的人和牌桌来的人，都得先过足球的算盘。",
                        "跨界运动员的卖点永远诱人：拳击手的核心力量、抗击打和一对一心理战，听起来就是为禁区肉搏定制的。但拳台纪律和禁区纪律有个致命差别——拳击里搂抱是技术，足球里搂抱是点球。凯利们的转型评估要盯紧“手部习惯”这一项：前臂卡位是艺术，双手上背是灾难。好消息是，拳击出身的人通常不怕挨骂，教练改造起来顺手。对抗可以教，胆量教不了，他两项都自带。", "“赌徒”型前锋则是转会市场的哲学题：十次过人九次失败，按常理该直接拉黑，但那一次成功如果出现在禁区里，期望值突然就翻正了。关键不在成功率，在出手位置——中圈浪过是送球权，禁区前沿的尝试叫造杀机。评估赌徒的正确姿势是画一张“尝试分布图”：点落在哪，他就值多少钱。本周王座俱乐部在找高水平替补门将，与这两位无关——本刊只是提醒：别在转会窗上头，那是赌徒的工作。",
                        "过人失败九次不可怕，可怕的是位置不对。", "核查清单", "拳击冠军：青少年重量级，已核。过人成功率：一成，属实。关键变量：尝试位置分布图，签约前务必索取。",
                        "", 11, 4),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "凯利：禁区里的重量级", "背身作战是他的舒适区，对方中锋的难受区。",
                        "身体对抗是拳台认证的：核心力量、平衡感、贴身缠斗的耐心，都是青少年重量级冠军的底子。背身防守尤其出色——对方中锋接球瞬间，他已经把位置站成了一堵墙。性格沉稳，被挑衅不上头，拳击教会他挨打之后的呼吸。定位球攻防两端都是武器，解围方式朴素但高效。", "转型遗留问题要列清楚：手部动作的习惯是点球隐患，裁判尺度严的联赛里学费不菲。转身速度与回追能力一般，身后球需要防线整体补偿。出球能力朴素，体系要求中卫组织时他会显得安静。拳击履历还带来一个体检重点：手部与肋部的陈旧伤，请队医逐页核对。",
                        "他在拳台学会了不怕，在禁区学会了不抱。", "体检提示", "重点核对：手部、肋部、鼻梁。拳击旧伤不是减分项，是知情项。冠军证书：青少年重量级，已核。",
                        "player.kelly.ryan", 4, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "门德斯：一成成功率的天才", "街头足球出身，过人如抽牌，十次九输，赢一次就收比赛。",
                        "创造力和胆识是真货：小范围的节奏变化、假动作的想象力，带着街头足球的原生味道。最关键的一点——他的尝试多集中在进攻三区：失败九次不丢大局，成功一次直接改写比分。心理素质异常好，失误后下一回合还敢做动作，这在“赌徒”型球员里是最稀有的品质。僵局与杯赛，是他的营业时间。", "风险清单同样坦诚：一成成功率意味着常规时间的产出极不稳定，联赛长跑里这种波动会磨掉教练的耐心。体能和防守投入都在及格线下，体系要为他留特权位。纪律层面的“赌性”是否只留在球场上，背景调查要做足——这句话不是玩笑。合同建议：底薪加进球助攻重奖，让赌徒为自己下注。",
                        "让他下注可以，筹码必须是他自己的奖金。", "尽调重点", "场上数据：尝试分布图必查。场下背景：“赌性”边界必查。前者定价格，后者定能不能谈。",
                        "player.mendes.ricardo", 23, -1)),
                Issue("mag.season.24", 20, 24,
                    "《绿金足球报》", "百场与三百场：小组收官特辑", "第 21 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "给他十米空间，你最好直接犯规", "小组赛收官夜，经验被重新标价。",
                        "安德烈·卡瓦略的葡超第一百场之后没有太多仪式，只有对手边后卫赛后主动来换球衣——据说是留作警示后人的教具。三场完整录像里，他的内切线路每次都一样，每次都拦不住。", "另一边的托马斯·格兰特正在准备英冠第三百场之后的又一场比赛。冲刺数据不再吓人，但更衣室里的分贝统计依旧全队第一。小组赛末段，这两种履历同时开始升值。",
                        "“出场数不会骗人，前提是它真的有出场数可查。”", "核对清单", "一百场：查赛程。三百场：查赛程。至于赛季初那份“四十一球”：先查是哪个联赛。",
                        "player.carvalho.andre", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "战术室", "小组赛最后一轮，算术题比战术板厚", "出线、排位与轮换之间，教练先做数学。",
                        "小组赛最后一轮的教练席像一间临时会计事务所：这边领先一个够不够，那边净胜球要不要追，替补席上人人都在心算，连第四官员举牌都像在报汇率。经验球员的价值在这九十分钟里不是跑动，而是让全队别在第 75 分钟集体掏出计算器。", "末轮还有一种暗战：领先的一方练习控制，落后的一方练习梭哈。前者需要有人把节奏降下来、把球护住、把犯规挑在对的位置；后者需要有人相信九十分钟够用。两种活都不上集锦，两种活都决定谁继续上班、谁开始解释赛制。",
                        "“末轮最重要的技术动作，是把比分牌看住。”", "末轮症状", "同时偷看另一块场地的比分；第 80 分钟全员心算净胜球；赛后发布会准备两套稿子。",
                        "player.grant.thomas", 23, 3),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "卡瓦略：反击里的猎鹰，落位后的问号", "一百场样本可信，使用说明书要配空间。",
                        "优势清清楚楚：葡超出场破百、欧战见过场面，爆发力是即插即用的那种。三场完整录像里，他的内切线路几乎不换花样，防守者知道他要干什么，还是拦不住。由守转攻时，他是那种让中后卫提前后悔站位的边锋。", "问号也清楚：阵地战里对方边后卫不退半步时，他的样本明显变薄；无球防守投入度随比分起伏。而“给他十米空间你最好直接犯规”的另一面是——越来越多对手真的选择了犯规，他制造定位球后的出勤率需要单独核查。",
                        "“给他空间是你的失误，不给他空间是你的工作。”", "适配条件", "反击体系、边路纵深、有中锋牵制。避免：全场围攻却无人能拉开宽度的阵地战。",
                        "player.carvalho.andre", 10, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "老将观察", "格兰特：三百场换来的嗓门", "领导力可以折算成多少积分，目前没人算清。",
                        "三百场英冠不是履历，是一部可以分集核查的纪录片：防线指挥、定位球站位、更衣室秩序，全部有多年录像和多位前队友的交叉证词。升级赛季他在场，保级泥潭赛季他也在场——后者往往更能说明一个队长的成色。", "风险写在体测单上：转身和回追已经不适合高位防线，连续一周双赛需要轮换配额，定位球防守里他更适合指挥而不是盯人。报价前请只用本赛季录像评估他的速度，不要用他自己的回忆，也不要用对手赛后的客气。",
                        "“队长袖标不能回追，但能让别人提前回追。”", "风险", "高位防线勿试；连续客场需轮换；速度评价请以今年录像为准，勿引用回忆录。",
                        "player.grant.thomas", 16, -1)),
                Issue("mag.season.26", 21, 26,
                    "《边线周刊》", "冬歇体检号：铁人标准与亲戚条款", "第 22 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "冬歇体检报告：铁人标准与亲戚条款", "假期结束，体测仪器和推荐电话一起响了。",
                        "菲利普·诺瓦克的冬歇体检据说只用了别人一半的时间——仪器找不到多余的东西可测，就像他的比赛里没有多余的动作。", "同期抵达事务所的还有一份由叔叔亲自递交的简历。封面写着“从小看着长大”，附件是一顿规格过高的家庭烧烤邀请函。冬歇期的球探工作，一半是读数，一半是读人。",
                        "“体检报告只回答身体问题，回答不了他叔叔是谁。”", "冬歇清单", "体脂、冲刺、心率、假期训练记录。亲属推荐信请移步另一个窗口。",
                        "player.novak.filip", -1, -1),
                    Page(MagazinePageLayout.Feature,
                        "体检室", "铁人不是不受伤，是受伤记录可以查", "全勤类的传说，请先从病历夹看起。",
                        "冬歇体检的正确打开方式是翻旧账：连续出场纪录要和伤病记录对着看，“异常健康”的结论要有医院抬头和日期。铁人标准第一条不是从不受伤，而是每次小伤都有完整的回归时间表。凡是体检报告比简历还薄的候选人，都值得多问一句：这些年你都在哪儿做的检查？", "与体检报告一起抵达的，还有亲戚条款类推荐。每逢窗口，“从小看着长大”的证明材料就准时加厚。本刊立场不变：亲属可以推荐，但不能作证。上一份由叔叔转交的影像资料里，关键画面被一块三明治挡住了号码；这一份，我们建议至少把三明治挪开再评估。",
                        "“全勤是一种能力，前提是打卡机没让别人代按。”", "核查顺序", "出场记录→伤病记录→训练出勤→推荐人与球员的确切亲属关系。",
                        "player.novak.filip", 2, 21),
                    Page(MagazinePageLayout.ScoutReport,
                        "球探报告", "诺瓦克：没有多余动作的人", "国家队履历可查，节奏稳定得像校准过。",
                        "看诺瓦克的录像像看一份校准证书：传球稳定，节奏感极好，几乎找不到多余动作。国家队预选赛出场记录真实可查，说明高压客场里也有人信任他。冬歇后的体测干净，假期训练记录完整——在这个行业，“完整”已经是稀缺品质。", "疑问同样具体：绝对速度一般，被逼抢时向前的意愿需要更多样本；节奏型球员换一个联赛，最先丢的往往不是技术而是熟悉的拍点。建议试训安排一场高强度对抗，专门观察他被贴身之后的第一脚。",
                        "“他的录像像钟表说明书——准确，但请确认你要的是钟表。”", "观察重点", "接球前观察次数；由守转攻第一脚方向；被贴身后的处理。",
                        "player.novak.filip", 23, -1),
                    Page(MagazinePageLayout.ScoutReport,
                        "风险报告", "小莫雷拉：亲戚条款年度测试案例", "简历很短，家庭关系很长。",
                        "先说能核实的：年轻，训练准点——叔叔负责接送；热情真实，工资要求处于市场地下室。试训里的无球跑动出人意料地积极，至少在追逐每一个球这件事上，他没有亲戚可以代劳。", "其余全是空白：没有正式比赛样本，唯一推荐人是叔叔，“给他个机会绝对能行”不构成战术分析。号码可见性未经核实，家庭烧烤出席记录不能折算成出场分钟。建议开放试训、关闭偏见，并把评估表与烧烤邀请函分开存档。",
                        "“每个天才都曾是某人的侄子，但不是每个侄子都是天才。”", "建议", "先看他踢球，再吃烤肉。两个场合请安排在不同日期。",
                        "player.moreira.andre.cousin", 22, -1)),
                Issue("mag.season.28", 22, 28,
                    "《冬季转会观察》", "冬窗开讯号：检点问题与最年轻纪录", "第 23 期",
                    Page(MagazinePageLayout.Cover,
                        "封面故事", "冬窗开张：新简历多了“检点”一栏", "里纳尔迪的直塞没有争议，争议在球场以外。",
                        "马泰奥·里纳尔迪的传球录像让三家俱乐部同时拿起电话，他的场外传闻又让其中两家同时放下。冬窗第一周的共识是：先定义什么叫“检点”，再谈价格。", "同一个清晨，卢卡斯·莫雷尔的最年轻纪录旧闻被重新翻出。纪录本身没有变化，变化的是冬窗给它贴的价格标签。开窗第一天，所有人都在给风险重新命名。",
                        "“传闻不能首发，但传闻能影响排兵布阵的胆量。”", "开窗三件事", "传闻分级、纪录核查、传真机预热。后两者有文件，前者只有语气。",
